using System.Data.Common;

namespace SchoolAdmission.Api.Data;

/// <summary>
/// The whole "data access framework": positional parameters and row mapping on top of
/// plain ADO.NET. Queries are few and concurrency-sensitive, so the SQL is written by hand
/// and kept visible rather than generated by an ORM.
/// </summary>
internal static class SqlExtensions
{
    /// <summary>Creates a command that borrows a pooled connection for one statement.</summary>
    public static DbCommand Sql(this DbDataSource dataSource, string sql, params object[] parameters) =>
        dataSource.CreateCommand(sql).Bind(parameters);

    /// <summary>Creates a command on an open connection, optionally inside a transaction.</summary>
    public static DbCommand Sql(this DbConnection connection, DbTransaction? transaction, string sql, params object[] parameters)
    {
        var command = connection.CreateCommand();
        command.CommandText = sql;
        command.Transaction = transaction;
        return command.Bind(parameters);
    }

    /// <summary>Binds values to $1, $2, ... in order. Values are never concatenated into SQL.</summary>
    private static DbCommand Bind(this DbCommand command, object[] parameters)
    {
        foreach (var value in parameters)
        {
            var parameter = command.CreateParameter();
            parameter.Value = value;
            command.Parameters.Add(parameter);
        }

        return command;
    }

    public static async Task<List<T>> QueryAsync<T>(this DbCommand command, Func<DbDataReader, T> map, CancellationToken ct)
    {
        await using (command)
        await using (var reader = await command.ExecuteReaderAsync(ct))
        {
            var rows = new List<T>();
            while (await reader.ReadAsync(ct))
            {
                rows.Add(map(reader));
            }

            return rows;
        }
    }

    public static async Task<T?> QuerySingleOrDefaultAsync<T>(this DbCommand command, Func<DbDataReader, T> map, CancellationToken ct)
        where T : class
    {
        await using (command)
        await using (var reader = await command.ExecuteReaderAsync(ct))
        {
            return await reader.ReadAsync(ct) ? map(reader) : null;
        }
    }

    public static async Task<int> ExecuteAsync(this DbCommand command, CancellationToken ct)
    {
        await using (command)
        {
            return await command.ExecuteNonQueryAsync(ct);
        }
    }
}
